package com.prestige.notification.api;
import com.prestige.notification.service.*; import java.time.LocalDateTime; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.http.MediaType; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
@RestController @RequestMapping("/api/v1/notifications") public class NotificationController {private final NotificationService service;private final NotificationBroker broker;public NotificationController(NotificationService service,NotificationBroker broker){this.service=service;this.broker=broker;} private Long id(Jwt jwt){return Long.valueOf(jwt.getSubject());}
 @GetMapping public NotificationPage list(@AuthenticationPrincipal Jwt jwt,@RequestParam(defaultValue="20") int limit,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) LocalDateTime before){return service.list(id(jwt),before,Math.min(Math.max(limit,1),100));}
 @PatchMapping("/{notificationId}/read") public NotificationResponse read(@AuthenticationPrincipal Jwt jwt,@PathVariable Long notificationId){return service.markRead(id(jwt),notificationId);}
 @GetMapping(value="/stream",produces=MediaType.TEXT_EVENT_STREAM_VALUE) public SseEmitter stream(@AuthenticationPrincipal Jwt jwt){return broker.connect(id(jwt));}}
